import assert from 'node:assert/strict';

/** One scenario against production Node HTTP and actual workerd/D1 routers. */
export async function exerciseAssignments({request,owner,member,workspaceId,restart,replaceMembership}){
 const base='/api/content/workspaces/'+workspaceId,ok=async(response,status=200)=>{assert.equal(response.status,status,await response.clone().text());assert.equal(response.headers.get('cache-control'),'no-store');return response.json();},get=(path,account=owner)=>request(base+path,{account});
 let revision=(await ok(await get('/pages'))).revision;
 const save=async(path,body={},options={})=>{const response=await request(base+path,{method:options.method??'POST',account:options.account??owner,body:{expectedRevision:revision,...body},headers:options.headers});const result=await ok(response,options.status??200);assert.equal(result.revision,revision+1);revision=result.revision;return result;};
 const collection=await save('/collections',{title:'Synthetic private assignment collection',parentId:null,properties:[{id:'assignee',name:'Assignee',type:'person'},{id:'note',name:'Original text',type:'text'}]},{status:201}),path='/collections/'+collection.collectionId,record=(await save(path+'/records',{title:'Synthetic assignment record',values:{assignee:null,note:'Original source text'}},{status:201})).record;
 const inbox=async()=>ok(await get('/notifications',member)),assign=value=>save(path+'/records/'+record.id,{values:{assignee:value}},{method:'PATCH'});
 assert.equal((await get('/pages/'+record.pageId,member)).status,404);await assign(member.id);assert.deepEqual((await inbox()).notifications,[]);assert.equal((await get('/pages/'+record.pageId,member)).status,404);
 await save('/pages/'+record.pageId+'/grants',{accountId:member.id,permission:'viewer'});await assign(member.id);assert.deepEqual((await inbox()).notifications,[]);await assign(null);await assign(member.id);let notices=(await inbox()).notifications;assert.equal(notices.length,1);const first=notices[0];assert.equal(first.reason,'assignment');assert.equal(first.pageId,record.pageId);assert.deepEqual(Object.keys(first).sort(),['id','pageId','pageTitle','authorId','createdAt','readAt','reason'].sort());assert.equal((await get('/pages/'+collection.pageId,member)).status,404);
 const text='Hello @Participant';await save('/pages/'+record.pageId+'/comments',{blockId:null,text,mentions:[{accountId:member.id,start:6,end:text.length}]});notices=(await inbox()).notifications;assert.equal(notices.length,2);assert.ok(notices.some(item=>item.reason==='mention'&&item.threadId&&item.text===text));
 const bodyText='担当 @Participant 👩‍💻',bodyMention={kind:'person',accountId:member.id,start:bodyText.indexOf('@'),end:bodyText.indexOf('@')+'@Participant'.length},writeBody=async blocks=>{const page=await ok(await get('/pages/'+record.pageId));return save('/pages/'+record.pageId,{expectedVersion:page.document.version,blocks},{method:'PATCH'});};
 const initialPage=await ok(await get('/pages/'+record.pageId)),originalBlocks=initialPage.document.blocks;await writeBody([...originalBlocks,{id:'inline-reference',type:'paragraph',data:{text:bodyText,mentions:[bodyMention]}}]);notices=(await inbox()).notifications;assert.equal(notices.length,3);const inline=notices.find(item=>item.reason==='inline-mention');assert.ok(inline);assert.deepEqual(Object.keys(inline).sort(),['id','pageId','pageTitle','authorId','createdAt','readAt','reason'].sort());assert.equal(inline.pageId,record.pageId);assert.equal((await get('/pages/'+collection.pageId,member)).status,404);
 await save('/notifications',{notificationIds:notices.map(item=>item.id)},{account:member});await assign(member.id);await writeBody([...originalBlocks,{id:'inline-moved',type:'paragraph',data:{text:'X '+bodyText,mentions:[{...bodyMention,start:bodyMention.start+2,end:bodyMention.end+2}]}}]);notices=(await inbox()).notifications;assert.equal(notices.find(item=>item.reason==='assignment').id,first.id);assert.equal(notices.find(item=>item.reason==='inline-mention').id,inline.id);assert.ok(notices.every(item=>item.readAt!==null));
 await restart();notices=(await inbox()).notifications;assert.equal(notices.length,3);assert.equal(notices.find(item=>item.reason==='assignment').id,first.id);assert.equal(notices.find(item=>item.reason==='inline-mention').id,inline.id);assert.ok(notices.every(item=>item.readAt!==null));
 const history=await ok(await get('/pages/'+record.pageId+'/history')),blank=history.versions.find(item=>item.version===initialPage.document.version),mentioned=history.versions.find(item=>item.version===initialPage.document.version+1);assert.ok(blank&&mentioned);const restoreBody=async id=>{const current=await ok(await get('/pages/'+record.pageId));return save('/pages/'+record.pageId+'/history/'+id+'/restore',{expectedVersion:current.document.version});};await restoreBody(blank.id);assert.equal((await inbox()).notifications.some(item=>item.reason==='inline-mention'),false);await restoreBody(mentioned.id);assert.equal((await inbox()).notifications.some(item=>item.reason==='inline-mention'),false);
 await writeBody(originalBlocks);assert.equal((await inbox()).notifications.some(item=>item.reason==='inline-mention'),false);await writeBody([...originalBlocks,{id:'inline-again',type:'paragraph',data:{text:bodyText,mentions:[bodyMention]}}]);const inlineAgain=(await inbox()).notifications.find(item=>item.reason==='inline-mention');assert.notEqual(inlineAgain.id,inline.id);assert.equal(inlineAgain.readAt,null);
 await assign(null);assert.equal((await inbox()).notifications.some(item=>item.reason==='assignment'),false);await assign(member.id);const replacement=(await inbox()).notifications.find(item=>item.reason==='assignment');assert.notEqual(replacement.id,first.id);assert.equal(replacement.readAt,null);
 const before=revision;for(const headers of [{'X-Yumunio-Expected-Account':owner.id},{Origin:'https://foreign.assignment.invalid'}]){const response=await request(base+'/notifications',{method:'POST',account:member,headers,body:{expectedRevision:revision,notificationIds:[replacement.id]}});assert.ok([403,404].includes(response.status));}assert.equal((await inbox()).revision,before);
 await replaceMembership(member.id);assert.deepEqual((await inbox()).notifications,[]);await save('/pages/'+record.pageId+'/grants',{accountId:member.id,permission:'viewer'});await assign(member.id);assert.deepEqual((await inbox()).notifications,[]);await assign(null);await assign(member.id);assert.equal((await inbox()).notifications.filter(item=>item.reason==='assignment').length,1);await writeBody([...originalBlocks,{id:'inline-again',type:'paragraph',data:{text:bodyText,mentions:[bodyMention]}}]);const rebound=(await inbox()).notifications.find(item=>item.reason==='inline-mention');assert.ok(rebound);assert.notEqual(rebound.id,inlineAgain.id);
 await save('/pages/'+record.pageId,{}, {method:'DELETE'});assert.deepEqual((await inbox()).notifications,[]);await save('/pages/'+record.pageId+'/restore');assert.deepEqual((await inbox()).notifications,[]);
 const result=await ok(await get(path+'/records/'+record.id));assert.equal(result.record.values.note,'Original source text');assert.equal(result.record.values.assignee,member.id);
}
